SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2009.YEAR, Станции2009.NUST, Станции2009.nr, Станции2009.E, Станции2009.EOTP, Станции2009.EURT, Станции2009.EUST, Станции2009.Q, Станции2009.TURT, Станции2009.TUST, Станции2009.B, Станции2009.GAZ, Доп_угли2009.gazpp, Станции2009.MAZUT, Станции2009.TORF, Станции2009.SLAN, Станции2009.PROCH, Станции2009.UGOL, Станции2009.DON, Станции2009.PODM, Станции2009.PECH, Доп_угли2009.int, Доп_угли2009.vork, Станции2009.ARKT, Станции2009.KUZN, Станции2009.URAL, Доп_угли2009.sver, Доп_угли2009.chel, Доп_угли2009.kizel, Станции2009.BASHK, Станции2009.EKIB, Станции2009.KARAG, Станции2009.KAN, Доп_угли2009.nazar, Доп_угли2009.ibor, Доп_угли2009.berez, Доп_угли2009.per, Станции2009.TUNG, Доп_угли2009.jer, Доп_угли2009.karab, Станции2009.IRKUT, Доп_угли2009.azey, Доп_угли2009.mug, Доп_угли2009.cher, Станции2009.HAK, Станции2009.TUV, Станции2009.BUR, Доп_угли2009.gusin, Доп_угли2009.tugn, Станции2009.CHIT, Доп_угли2009.har, Доп_угли2009.urt, Станции2009.NER AS Выражение1, Доп_угли2009.neru, Доп_угли2009.pyak, Станции2009.RAICH AS Выражение2, Доп_угли2009.rai, Доп_угли2009.erk, Станции2009.URG, Станции2009.PRIM, Станции2009.LUCH, Станции2009.MAG, Станции2009.SAH, Станции2009.USHUM, Станции2009.QOTR, Станции2009.SNK, Станции2009.EWTP, Станции2009.NT, Станции2009.OBOR, Станции2009.VED, Станции2009.OBL, Станции2009.DEP, Станции2009.OES, Станции2009.ER, Станции2009.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Станции2009.NTsum, Станции2009.GK, Станции2009.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM ((((((Станции2009 INNER JOIN Имена_станций ON Станции2009.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2009.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2009.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2009 ON (Станции2009.YEAR=Доп_угли2009.YEAR) AND (Станции2009.NUMB1120=Доп_угли2009.NUMB1120)) LEFT JOIN имена_ГК ON Станции2009.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2009.BE=имена_БЕ.code) LEFT JOIN Города ON Имена_станций.codegor=Города.code;
